package me.pikanote.companion;
import android.app.Instrumentation;import android.os.Bundle;import java.io.*;import java.nio.file.Files;import java.util.zip.*;
public class MigrationBridge extends Instrumentation{
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();try{File root=getTargetContext().getFilesDir();int count=0;try(ZipInputStream zip=new ZipInputStream(new FileInputStream("/data/local/tmp/pika-migration.zip"))){ZipEntry entry;while((entry=zip.getNextEntry())!=null){String name=entry.getName();if(name.contains("..")||name.startsWith("/"))throw new IOException("Invalid migration path");File file=new File(root,name);file.getParentFile().mkdirs();byte[] bytes=zip.readAllBytes();if(file.getName().endsWith(".aes")){if(name.equals("phone-store.aes")){String text=new String(bytes,java.nio.charset.StandardCharsets.UTF_8);org.json.JSONObject state=new org.json.JSONObject(text);for(String key:new String[]{"deviceSecrets","restoreDeviceSecrets"}){org.json.JSONObject old=state.optJSONObject(key);if(old!=null){org.json.JSONObject next=new org.json.JSONObject();java.util.Iterator<String> keys=old.keys();while(keys.hasNext()){String k=keys.next();next.put(BrandCompatibility.normalize(k),old.get(k));}state.put(key,next);}}bytes=state.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);}Vault.write(file,bytes);}else Files.write(file.toPath(),bytes);count++;}}result.putInt("files",count);result.putString("status","imported");finish(-1,result);}catch(Exception e){result.putString("error",e.toString());finish(0,result);}}
}